import React, { useContext } from 'react';
import { Container, Navbar, Nav, NavDropdown } from 'react-bootstrap';
import { useNavigate, Link } from 'react-router-dom';
import { FaUserCircle, FaSignOutAlt, FaHome } from 'react-icons/fa';
import { AuthContext } from '../../App';

const COMPANY_NAME = process.env.SCHOOL_NAME || 'Institute User Portal';

function Header() {
  const { stateAuth, dispatchAuth } = useContext(AuthContext);
  const navigate = useNavigate();

  const userName = stateAuth?.user ? stateAuth.user.stdnm || stateAuth.user.stfnm || stateAuth.user.drvnm || stateAuth.user.emlid : 'User';

  const logout = () => {
    dispatchAuth({ type: 'LOGOUT' });
    navigate('/');
  };

  return (
    <Navbar bg="primary" variant="dark" expand="lg" sticky="top">
      <Container fluid>
        <Navbar.Brand as={Link} to="/dashboard">
          {COMPANY_NAME}
        </Navbar.Brand>
        <Navbar.Toggle aria-controls="basic-navbar-nav" />
        <Navbar.Collapse id="basic-navbar-nav">
          <Nav className="me-auto">
            <Nav.Link as={Link} to="/dashboard">
              <FaHome /> Dashboard
            </Nav.Link>
          </Nav>
          <Nav>
            <NavDropdown title={<span><FaUserCircle /> {userName}</span>} id="user-dropdown" align="end">
              <NavDropdown.Item as={Link} to="/profile">My Profile</NavDropdown.Item>
              <NavDropdown.Divider />
              <NavDropdown.Item onClick={logout}>
                <FaSignOutAlt /> Logout
              </NavDropdown.Item>
            </NavDropdown>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
}

export default Header;
